<?php
require_once __DIR__.'/config.php'; require_login();
if(($_SESSION['rol']??'')==='Administrador'){header('Location: admin.php');exit;}
verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 try { $action=$_POST['action']??'';
  if($action==='community_player'){
   $nombre=trim($_POST['nombre']??'');$apellido=trim($_POST['apellido']??'');$team=(int)($_POST['id_equipo']??0);$pos=trim($_POST['posicion']??'');$num=($_POST['numero_camiseta']??'')!==''?(int)$_POST['numero_camiseta']:null;
   if($nombre===''||$apellido==='')throw new RuntimeException('Escribe nombre y apellido.');
   $code='MS-'.strtoupper(bin2hex(random_bytes(5)));$q=$conexion->prepare('INSERT INTO jugador(id_equipo,nombre,apellido,codigo_estudiante,numero_camiseta,posicion) VALUES(NULLIF(?,0),?,?,?, ?,?)');$q->bind_param('isssis',$team,$nombre,$apellido,$code,$num,$pos);$q->execute();flash('Jugador registrado correctamente.','success',true);
  } elseif($action==='community_match'){
   $local=(int)($_POST['local']??0);$visitante=(int)($_POST['visitante']??0);$disc=trim($_POST['disciplina']??'Fútbol');$fecha=str_replace('T',' ',$_POST['fecha_partido']??'');
   if(!$local||!$visitante||$local===$visitante||$fecha==='')throw new RuntimeException('Elige dos equipos distintos y una fecha.');
   $estado='Programado';$fair=100;$q=$conexion->prepare('INSERT INTO partido(id_equipo_local,id_equipo_visitante,disciplina,fecha_partido,estado,fair_play) VALUES(?,?,?,?,?,?)');$q->bind_param('iisssi',$local,$visitante,$disc,$fecha,$estado,$fair);$q->execute();flash('Partido registrado correctamente.','success',true);
  } else throw new RuntimeException('Acción no válida.');
 } catch(Throwable $ex){flash($ex instanceof RuntimeException?$ex->getMessage():'No se pudo guardar. Revisa los datos e inténtalo de nuevo.','error');}
 header('Location: estudiante.php#'.(($_POST['action']??'')==='community_player'?'jugadores':'calendario'));exit;
}
$players=$conexion->prepare('SELECT j.*,e.nombre_equipo FROM jugador j LEFT JOIN equipo e ON e.id_equipo=j.id_equipo ORDER BY j.apellido,j.nombre');$players->execute();$allPlayers=$players->get_result()->fetch_all(MYSQLI_ASSOC);
$matches=$conexion->query("SELECT p.*,l.nombre_equipo local_nombre,v.nombre_equipo visitante_nombre FROM partido p JOIN equipo l ON l.id_equipo=p.id_equipo_local JOIN equipo v ON v.id_equipo=p.id_equipo_visitante WHERE p.estado <> 'Suspendido' ORDER BY p.fecha_partido DESC LIMIT 12")->fetch_all(MYSQLI_ASSOC);
$teams=$conexion->query('SELECT e.*,COUNT(j.id_jugador) total_jugadores FROM equipo e LEFT JOIN jugador j ON j.id_equipo=e.id_equipo GROUP BY e.id_equipo ORDER BY e.nombre_equipo')->fetch_all(MYSQLI_ASSOC);
$profilePhoto='';$photoQuery=$conexion->prepare('SELECT foto_perfil FROM perfil_usuario WHERE id_usuario=?');$photoQuery->bind_param('i',$_SESSION['usuario_id']);$photoQuery->execute();$photoRow=$photoQuery->get_result()->fetch_assoc();$profilePhoto=$photoRow['foto_perfil']??'';?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mi espacio | MokaSports</title><link rel="stylesheet" href="assets/style.css"></head><body class="app-body student-body"><aside class="sidebar"><a class="brand" href="estudiante.php"><span class="brand-mark">M</span><span>MokaSports</span></a><div class="side-label">MI ESPACIO</div><a class="side-link active" href="#inicio">▦ <span>Resumen</span></a><a class="side-link" href="#calendario">◷ <span>Partidos</span></a><a class="side-link" href="#equipos">◈ <span>Equipos</span></a><a class="side-link" href="#jugadores">♙ <span>Jugadores</span></a><a class="side-link" href="#juego-limpio">♡ <span>Juego limpio</span></a><div class="sidebar-bottom"><a class="side-link" href="perfil.php">◎ <span>Editar mi perfil</span></a><div class="user-mini"><span class="avatar"><?php if($profilePhoto):?><img src="<?=e($profilePhoto)?>" alt="Foto de perfil"><?php else:?><?=e(mb_substr($_SESSION['nombre']??'E',0,1))?><?php endif;?></span><div><b><?=e($_SESSION['nombre']??'Estudiante')?></b><small>Estudiante</small></div></div><a class="side-link" href="logout.php">↪ <span>Cerrar sesión</span></a></div></aside><main class="main-content"><header class="topbar" id="inicio"><div><span class="eyebrow">TU COMUNIDAD DEPORTIVA</span><h1>¡Hola, <?=e($_SESSION['nombre']??'deportista')?>!</h1><p class="muted">Consulta los encuentros y conoce a los equipos de tu comunidad.</p></div><div class="top-actions"><button class="theme-toggle" type="button">♡ <span>Modo rosita</span></button><a class="btn btn-secondary" href="perfil.php">Editar perfil</a><span class="role-chip">● Estudiante</span></div></header><?php show_flash(); ?><section class="welcome-banner"><div><span class="eyebrow">EL JUEGO LIMPIO EMPIEZA CONTIGO</span><h2>Respeta. Colabora. Da lo mejor.</h2><p>El resultado importa; la forma en que jugamos también.</p></div><div class="banner-ball">◎</div></section><section class="stats-grid three-stats"><article class="stat-card"><span class="stat-label">Equipos activos</span><strong><?=count($teams)?></strong><small>Disciplinas de la comunidad</small></article><article class="stat-card"><span class="stat-label">Jugadores registrados</span><strong><?=count($allPlayers)?></strong><small>Deportistas en la plataforma</small></article><article class="stat-card"><span class="stat-label">Partidos publicados</span><strong><?=count($matches)?></strong><small>Encuentros visibles</small></article></section><section id="calendario" class="content-section"><div class="section-heading"><div><span class="eyebrow">ENCUENTROS</span><h2>Calendario de partidos</h2><p class="muted">Revisa las fechas, estados y marcadores disponibles.</p></div></div><form method="post" class="editor-card compact-editor"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="community_match"><div class="editor-title">＋ Proponer un partido</div><div class="form-grid"><label>Equipo local<select name="local" required><option value="">Seleccionar</option><?php foreach($teams as $t):?><option value="<?=$t['id_equipo']?>"><?=e($t['nombre_equipo'])?></option><?php endforeach;?></select></label><label>Equipo visitante<select name="visitante" required><option value="">Seleccionar</option><?php foreach($teams as $t):?><option value="<?=$t['id_equipo']?>"><?=e($t['nombre_equipo'])?></option><?php endforeach;?></select></label><label>Disciplina<input name="disciplina" value="Fútbol" required></label><label>Fecha y hora<input type="datetime-local" name="fecha_partido" required></label></div><button class="btn btn-primary" type="submit">Agregar partido</button><p class="muted small-note">Los partidos propuestos por estudiantes se publican como programados.</p></form><div class="table-wrap"><table><thead><tr><th>Encuentro</th><th>Fecha</th><th>Estado</th><th>Marcador</th><th>Fair Play</th></tr></thead><tbody><?php if(!$matches):?><tr><td colspan="5" class="empty-state">Todavía no hay partidos publicados.</td></tr><?php endif;foreach($matches as $m):?><tr><td><b><?=e($m['local_nombre'])?></b><div class="muted">vs. <?=e($m['visitante_nombre'])?></div></td><td><?=e(date('d/m/Y H:i',strtotime($m['fecha_partido'])))?></td><td><span class="status status-<?=strtolower(str_replace(' ','-',e($m['estado'])))?>"><?=e($m['estado'])?></span></td><td><b><?=($m['puntos_local']===null?'—':(int)$m['puntos_local'])?> : <?=($m['puntos_visitante']===null?'—':(int)$m['puntos_visitante'])?></b></td><td><?= (int)$m['fair_play'] ?>/100</td></tr><?php endforeach;?></tbody></table></div></section><section id="equipos" class="content-section"><div class="section-heading"><div><span class="eyebrow">COMUNIDAD</span><h2>Equipos</h2></div></div><div class="team-grid"><?php if(!$teams):?><div class="empty-state">Todavía no hay equipos registrados.</div><?php endif;foreach($teams as $t):?><article class="team-card"><span class="team-symbol">◈</span><div><h3><?=e($t['nombre_equipo'])?></h3><p><?=e($t['disciplina'])?> · <?=e($t['seccion']?:'Sección no indicada')?></p><small><?= (int)$t['total_jugadores']?> jugadores</small></div></article><?php endforeach;?></div></section><section id="jugadores" class="content-section"><div class="section-heading"><div><span class="eyebrow">DEPORTISTAS</span><h2>Jugadores registrados</h2></div></div><form method="post" class="editor-card compact-editor"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="community_player"><div class="editor-title">＋ Agregar jugador</div><div class="form-grid"><label>Nombre<input name="nombre" required maxlength="100"></label><label>Apellido<input name="apellido" required maxlength="100"></label><label>Equipo<select name="id_equipo"><option value="0">Sin equipo</option><?php foreach($teams as $t):?><option value="<?=$t['id_equipo']?>"><?=e($t['nombre_equipo'])?></option><?php endforeach;?></select></label><label>Posición<input name="posicion" maxlength="50" placeholder="Ej. Delantero"></label><label>Número de camiseta<input name="numero_camiseta" type="number" min="0" max="255"></label></div><button class="btn btn-primary" type="submit">Guardar jugador</button></form><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Equipo</th><th>Posición</th><th>Camiseta</th></tr></thead><tbody><?php if(!$allPlayers):?><tr><td colspan="4" class="empty-state">Todavía no hay jugadores registrados.</td></tr><?php endif;foreach($allPlayers as $p):?><tr><td><b><?=e($p['nombre'].' '.$p['apellido'])?></b></td><td><?=e($p['nombre_equipo']?:'Sin equipo')?></td><td><?=e($p['posicion']?:'—')?></td><td><?=e($p['numero_camiseta']??'—')?></td></tr><?php endforeach;?></tbody></table></div></section><section id="juego-limpio" class="content-section fairplay-section"><div class="section-heading"><div><span class="eyebrow">DEPORTE CON VALORES</span><h2>Recomendaciones para un juego limpio</h2><p class="muted">¡Competir es mejor cuando todas las personas se sienten respetadas!</p></div></div><div class="fairplay-grid"><article class="fairplay-card"><img src="assets/gatos-amigas.jpg" alt="Dos gatitos decorativos con coronas" loading="lazy"><div class="fairplay-copy"><span class="fairplay-number">01 · RESPETO</span><h3>Respeta a todos</h3><p>Trata con amabilidad a compañeros, rivales, árbitros y entrenadores. Nada de insultos ni burlas.</p></div></article><article class="fairplay-card"><img src="assets/gatos-baile.gif" alt="GIF divertido de gatitos bailando" loading="lazy"><div class="fairplay-copy"><span class="fairplay-number">02 · HONESTIDAD</span><h3>Juega con honestidad</h3><p>Acepta las decisiones arbitrales, reconoce tus errores y compite sin trampas.</p></div></article><article class="fairplay-card"><img src="assets/gatos-corona.gif" alt="GIF divertido de un animalito cocinando" loading="lazy"><div class="fairplay-copy"><span class="fairplay-number">03 · EQUIPO</span><h3>Apoya a tu equipo</h3><p>Anima sin humillar al otro equipo. Comparte el balón, ayuda a tus compañeros y celebra con humildad.</p></div></article></div><div class="fairplay-pledge"><span class="pledge-heart">♡</span><div><h3>Mi compromiso deportivo</h3><p>Me comprometo a respetar, ser honesto, ayudar a mi equipo y disfrutar el deporte sin violencia.</p></div><span class="pledge-tag">#JuegoLimpio</span></div></section><footer class="app-footer">MokaSports <span>·</span> Juega limpio, crece en equipo.</footer></main><script src="assets/app.js"></script></body></html>
